SketchHUDConstraintAdapter::SketchHUDConstraintAdapter(Sketcher::SketchObject& sketch)
    : sketchObject(sketch)
{
}

int SketchHUDConstraintAdapter::injectLengthConstraint(int lineGeoId, double lengthValue)
{
    // Create native Sketcher::Constraint of type Distance
    Sketcher::Constraint c;
    c.Type = Sketcher::Constraint::Distance;
    c.First = lineGeoId;
    c.FirstPos = Sketcher::PointPos::none;
    c.setValue(lengthValue);

    return sketchObject.addConstraint(c);
}

int SketchHUDConstraintAdapter::injectAngleConstraint(int lineGeoId, double angleDegrees)
{
    // Create native Sketcher::Constraint of type Angle
    Sketcher::Constraint c;
    c.Type = Sketcher::Constraint::Angle;
    c.First = lineGeoId;
    c.FirstPos = Sketcher::PointPos::none;
    c.Second = Sketcher::GeoEnum::HAxis;
    c.SecondPos = Sketcher::PointPos::none;
    c.setValue(angleDegrees * (M_PI / 180.0));

    return sketchObject.addConstraint(c);
}

