 */
struct GridSnapResult
{
    bool snapped = false;
    Base::Vector3d snappedPos;
    Base::Vector3d originalPos;
    double snapDistance = 0.0;
    const char* snapGlyph = ""; // "grid", "intersection", "origin", "midpoint"
};

/**
 * @class GridManager
 * @brief Continuous screen-space and plane-space dynamic grid rendering
