double GridManager::calculateAdaptiveGridSpacing(double viewportScale) const
{
    if (viewportScale <= 0.0) return baseGridSize;

    double targetPixelSpacing = 30.0; // Ideal grid cell density in pixels
    double worldSpacing = targetPixelSpacing / viewportScale;

    // Logarithmic power-of-10 base scaling with sub-divisions (1mm, 0.5mm, 0.1mm)
    double power = std::pow(10.0, std::floor(std::log10(worldSpacing)));
    double relative = worldSpacing / power;

    if (relative < 2.0) {
        return 1.0 * power;
    } else if (relative < 5.0) {
        return 2.0 * power;
    } else {
        return 5.0 * power;
    }
}

